import 'package:flutter/material.dart';
import '../core/theme_controller.dart';
import '../database/db_helper.dart';
class PlantelScreen extends StatefulWidget{final AppThemeController theme;const PlantelScreen({super.key,required this.theme});@override State<PlantelScreen> createState()=>_PlantelState();}
class _PlantelState extends State<PlantelScreen>{List<Map<String,Object?>> rows=[];String q='';@override void initState(){super.initState();load();}Future<void>load()async{final d=await DBHelper.db;rows=await d.query('aves',where:'status=?',whereArgs:['ATIVA'],orderBy:'id DESC');setState((){});}Future<void>edit([Map<String,Object?>? old])async{final an=TextEditingController(text:old?['anilha'] as String? ?? ''),nome=TextEditingController(text:old?['nome'] as String? ?? ''),g=TextEditingController(text:old?['gaiola'] as String? ?? ''),obs=TextEditingController(text:old?['observacoes'] as String? ?? '');String sexo=old?['sexo'] as String? ?? 'Macho';String seg=old?['segmento'] as String? ?? 'Cor';String top=(old?['topete'] as int? ?? 0)==1?'Sim':'Não';String origem=old?['origem'] as String? ?? 'Nascido no canaril';final fob=TextEditingController(text:old?['raca'] as String? ?? '');final result=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(old==null?'Nova ave':'Editar ave'),content:SizedBox(width:500,child:SingleChildScrollView(child:Column(children:[TextField(controller:an,decoration:const InputDecoration(labelText:'Anilha *')),TextField(controller:nome,decoration:const InputDecoration(labelText:'Nome (opcional)')),TextField(controller:g,decoration:const InputDecoration(labelText:'Gaiola')),DropdownButtonFormField(value:sexo,items:['Macho','Fêmea','Indeterminado'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>sexo=x!,decoration:const InputDecoration(labelText:'Sexo')),DropdownButtonFormField(value:seg,items:['Cor','Porte','Canto'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>seg=x!,decoration:const InputDecoration(labelText:'Segmento FOB')),TextField(controller:fob,decoration:const InputDecoration(labelText:'Raça / variedade FOB')),DropdownButtonFormField(value:top,items:['Sim','Não'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>top=x!,decoration:const InputDecoration(labelText:'Topete')),DropdownButtonFormField(value:origem,items:['Nascido no canaril','Pet shop','Outro canaril'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>origem=x!,decoration:const InputDecoration(labelText:'Origem')),TextField(controller:obs,maxLines:3,decoration:const InputDecoration(labelText:'Observações'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Salvar'))]));if(result!=true||an.text.trim().isEmpty)return;final d=await DBHelper.db;final data={'anilha':an.text.trim(),'nome':nome.text.trim(),'gaiola':g.text.trim(),'sexo':sexo,'segmento':seg,'raca':fob.text.trim(),'topete':top=='Sim'?1:0,'origem':origem,'observacoes':obs.text.trim(),'criado_em':DateTime.now().toIso8601String()};if(old==null)await d.insert('aves',data);else await d.update('aves',data,where:'id=?',whereArgs:[old['id']]);await load();}
Future<void>discharge(Map<String,Object?> r)async{final reason=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Baixar ave'),content:TextField(controller:reason,decoration:const InputDecoration(labelText:'Motivo: venda, doação, morte, aposentadoria...')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Confirmar'))]));if(ok==true){final d=await DBHelper.db;await d.insert('baixas',{'ave_id':r['id'],'data':DateTime.now().toIso8601String(),'motivo':reason.text,'destino':reason.text});await d.update('aves',{'status':'INATIVA'},where:'id=?',whereArgs:[r['id']]);load();}}
@override Widget build(BuildContext c){final filtered=rows.where((r){final s='${r['anilha']} ${r['nome']} ${r['raca']}'.toLowerCase();return s.contains(q.toLowerCase());}).toList();return Scaffold(appBar:AppBar(title:const Text('Plantel')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('Nova ave')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Buscar por anilha, nome ou raça'))),Expanded(child:ListView.builder(itemCount:filtered.length,itemBuilder:(c,i){final r=filtered[i];return Card(margin:const EdgeInsets.fromLTRB(12,0,12,8),child:ListTile(leading:CircleAvatar(child:Icon(r['sexo']=='Macho'?Icons.male:Icons.female)),title:Text('${r['anilha']}  ${r['nome']??''}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${r['sexo']} · Gaiola ${r['gaiola']??'-'} · ${r['raca']??'Sem raça'}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='edit')edit(r);if(v=='out')discharge(r);},itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:Text('Editar')),PopupMenuItem(value:'out',child:Text('Baixar sem apagar histórico'))])));} ))]));}}
